"""Previews and blur: reaction preview tests and per-streamer blur profiles."""
from __future__ import annotations
import json
import os
import re
import queue
import threading
from pathlib import Path
import flet as ft
import manual_blur
from .common import card,chip,muted,note,page_header,empty,MUTED


class PreviewView:
    """Previews generated by ChatGPT from a template thumbnail (auto: other clip channels; manual: your folder)."""
    def __init__(self,app):
        self.app=app;self.running=False;self._key=None;self._thumbs={};self.busy=set()
        p=app.config['pipeline']['preview']
        self.enabled=ft.Switch(label='Создавать превью для каждой нарезки через ChatGPT',value=bool(p['enabled']),on_change=lambda e:app.spawn(self._save))
        self.streamer=ft.TextField(label='Стример для тестовых видео',value=p.get('test_streamer',''),width=300,
                                   on_blur=lambda e:app.spawn(self._save),on_submit=lambda e:app.spawn(self._save))
        self.rows=ft.Column(spacing=12)
        self.ring=ft.ProgressRing(width=18,height=18,stroke_width=2,visible=False)
        self.status=ft.Text('',size=13)
        self.result=ft.Column(spacing=10)
        self.view=ft.Column([
            page_header('Превью','ChatGPT переделывает шаблон-обложку под надпись и контекст нарезки'),
            card(self.enabled,self.streamer,
                 note('Надпись и контекст для каждой нарезки ChatGPT пишет в том же запросе, где ищет моменты. '
                      'Затем отдельным запросом отправляется случайный шаблон и просьба: «Сделай мне такое же превью, но конечно улучши его визуально… '
                      'измени текст на мой: <надпись>, контекст: <контекст>». Каждое превью — один запрос генерации картинки.'),
                 title='Настройки',icon=ft.Icons.TUNE),
            card(self.rows,title='Шаблоны по стримерам',icon=ft.Icons.COLLECTIONS,
                 subtitle='Авто — обложки с чужих каналов нарезок этого стримера. Вручную — свои картинки в папке (2–10 и больше), берётся случайная.'),
            card(ft.Row([ft.FilledButton('Сгенерировать превью для нарезки…',icon=ft.Icons.AUTO_AWESOME,on_click=lambda e:app.spawn(self._test))],spacing=10),
                 ft.Row([self.ring,self.status],spacing=10),self.result,
                 title='Проверить',icon=ft.Icons.SCIENCE,subtitle='Выберите MP4 из папки recordings — новый запрос моментов не нужен'),
        ],spacing=16,scroll=ft.ScrollMode.AUTO,expand=True)

    # ---------- per-streamer templates ----------
    def _logins(self):
        c=self.app.config;names=list(c.get('streamers',[]))
        # Streamers added by link or with a channel card (e.g. leva2k) also get templates and a prompt.
        names+=[k for k in (c.get('streamer_modes') or {}) if k not in names and k!='__test__']
        t=c['pipeline']['preview'].get('test_streamer','')
        if t and t not in names:names.append(t)
        return names

    def refresh(self,snap):
        import gpt_previews as gp
        cfg=self.app.config['pipeline']['preview'];root=self.app.root;data=[]
        for login in self._logins():
            manual=gp.list_images(gp.manual_dir(root,login));auto=gp.list_images(gp.auto_dir(root,login))
            try:channels=[c['name'] for c in json.loads((gp.auto_dir(root,login)/'channels.json').read_text(encoding='utf-8')).get('channels',[])]
            except (OSError,ValueError):channels=[]
            data.append((login,gp.template_mode(cfg,login),tuple(p.name for p in manual),tuple(p.name for p in auto),tuple(channels),login in self.busy,
                         gp.prompt_intro(cfg,login),login in (cfg.get('prompts') or {}),tuple(gp.pinned_channels(login,cfg))))
        key=tuple(data)
        if key==self._key:return
        self._key=key
        self.rows.controls=[self._row(*d) for d in data] or [empty('Добавьте стримеров в настройках.')]

    def _thumb(self,path):
        import thumbnail_assets as ta
        k=(str(path),path.stat().st_mtime_ns)
        if k not in self._thumbs:
            try:self._thumbs[k]=ta.thumbnail_bytes(path,height=72)
            except Exception:self._thumbs[k]=None
        return self._thumbs[k]

    def _row(self,login,mode,manual,auto,channels,busy,intro='',custom=False,pinned=()):
        import gpt_previews as gp
        app=self.app;root=app.root
        seg=ft.SegmentedButton(segments=[ft.Segment(value='auto',label=ft.Text('Авто')),ft.Segment(value='manual',label=ft.Text('Вручную'))],
                               selected=[mode],on_change=lambda e,l=login:app.spawn(self._set_mode,l,(e.control.selected or ['auto'])[0]))
        folder=gp.auto_dir(root,login) if mode=='auto' else gp.manual_dir(root,login)
        names=auto if mode=='auto' else manual
        tiles=[]
        for name in names[:10]:
            data=self._thumb(folder/name)
            if data:tiles.append(ft.Container(ft.Image(src=data,height=72,fit=ft.BoxFit.CONTAIN),border_radius=6,tooltip=name))
        info=[chip(f'с чужих каналов: {len(auto)}','info' if auto else 'muted'),chip(f'своих: {len(manual)}','info' if manual else 'muted')]
        if busy:info.append(chip('ищу каналы…','warn',ft.Icons.HOURGLASS_TOP))
        actions=[ft.FilledTonalButton('Найти каналы нарезок',icon=ft.Icons.TRAVEL_EXPLORE,disabled=busy,on_click=lambda e,l=login:app.spawn(self._refresh_auto,l)),
                 ft.OutlinedButton('Папка своих шаблонов',icon=ft.Icons.FOLDER_OPEN,on_click=lambda e,l=login:self._open_manual(l))]
        body=[ft.Row([ft.Icon(ft.Icons.PERSON,color=ft.Colors.PRIMARY),ft.Text(login,size=16,weight=ft.FontWeight.W_600),seg,*info],spacing=12,wrap=True,
                     vertical_alignment=ft.CrossAxisAlignment.CENTER)]
        if mode=='auto' and channels:body.append(muted('Каналы: '+', '.join(channels),size=12))
        body.append(ft.Row(tiles,spacing=8,wrap=True) if tiles else muted('Шаблонов пока нет — '+('нажмите «Найти каналы нарезок»' if mode=='auto' else 'положите картинки в папку своих шаблонов'),size=12))
        body.append(ft.Row(actions,spacing=8,wrap=True))
        # YouTube channels whose thumbnails are always used as samples (even the streamer's own channel).
        pins=ft.TextField(label='Каналы-образцы превью (ссылки YouTube, каждая с новой строки)',value='\n'.join(pinned),multiline=True,min_lines=1,max_lines=6,text_size=13)
        save_pins=ft.FilledTonalButton('Сохранить каналы и обновить',icon=ft.Icons.SAVE,disabled=busy,on_click=lambda e,l=login,f=pins:app.spawn(self._save_channels,l,f.value))
        body.append(pins)
        body.append(ft.Row([save_pins,muted('Образцы берутся с этих каналов + с лучших найденных нарезчиков.',size=12)],spacing=8,wrap=True,
                           vertical_alignment=ft.CrossAxisAlignment.CENTER))
        # Opening of the ChatGPT request for this streamer; caption and context are appended by the bot.
        field=ft.TextField(label='Промпт превью (начало запроса)',value=intro,multiline=True,min_lines=2,max_lines=6,text_size=13)
        save=ft.FilledTonalButton('Сохранить промпт',icon=ft.Icons.SAVE,on_click=lambda e,l=login,f=field:app.spawn(self._save_prompt,l,f.value))
        reset=ft.TextButton('Вернуть стандартный',icon=ft.Icons.RESTART_ALT,disabled=not custom,on_click=lambda e,l=login:app.spawn(self._save_prompt,l,None))
        body.append(field)
        body.append(ft.Row([save,reset,chip('свой промпт' if custom else 'стандартный промпт','info' if custom else 'muted')],spacing=8,wrap=True,
                           vertical_alignment=ft.CrossAxisAlignment.CENTER))
        body.append(muted('Дальше бот сам допишет: «<надпись превью>» и с новой строки «контекст: <контекст>».',size=12))
        return ft.Container(ft.Column(body,spacing=10,tight=True),bgcolor='#1d2026',border_radius=12,padding=14)

    async def _set_mode(self,login,mode):
        if self.app.save_config(lambda c:c['pipeline']['preview'].setdefault('templates',{}).update({login:mode})):
            self._key=None;self.app.refresh_soon()

    async def _save_prompt(self,login,value):
        import gpt_previews as gp
        text=(value or '').replace('\r\n','\n').strip()
        if text==gp.DEFAULT_INTRO:text=''
        if len(text)>2000:await self.app.dialogs.error('Промпт превью','Не длиннее 2000 символов.');return
        def change(c):
            prompts=c['pipeline']['preview'].setdefault('prompts',{})
            if text:prompts[login]=text
            else:prompts.pop(login,None)
        if self.app.save_config(change):
            self.app.dialogs.toast(f'{login}: '+('свой промпт сохранён' if text else 'стандартный промпт'),'ok')
            self._key=None;self.app.refresh_soon()

    async def _save_channels(self,login,value):
        items=[x.strip() for x in re.split(r'[\s,;]+',value or '') if x.strip()]
        bad=[x for x in items if not re.search(r'youtube\.com/|youtu\.be/|^@[\w.-]+$|^UC[\w-]{22}$',x)]
        if bad:await self.app.dialogs.error('Каналы-образцы','Не похоже на ссылку на YouTube-канал: '+', '.join(bad[:3]));return
        def change(c):
            chans=c['pipeline']['preview'].setdefault('channels',{})
            if items:chans[login]=items
            else:chans.pop(login,None)
        if self.app.save_config(change):
            self.app.dialogs.toast(f'{login}: каналов-образцов {len(items)}, обновляю шаблоны','ok')
            self._key=None
            await self._refresh_auto(login)

    def _open_manual(self,login):
        import gpt_previews as gp
        folder=gp.manual_dir(self.app.root,login);folder.mkdir(parents=True,exist_ok=True);self.app.open_path(str(folder))

    async def _refresh_auto(self,login):
        import asyncio,gpt_previews as gp
        app=self.app;self.busy.add(login);self._key=None;app.refresh_soon()
        try:
            count,channels=await asyncio.to_thread(gp.refresh_auto,app.root,login,lambda m:app.service.log('Превью: '+m))
            app.dialogs.toast(f'{login}: шаблонов {count} с каналов: '+', '.join(channels),'ok')
        except Exception as exc:await app.dialogs.error('Шаблоны',str(exc))
        finally:self.busy.discard(login);self._key=None;app.refresh_soon()

    # ---------- settings ----------
    async def _save(self):
        value=bool(self.enabled.value);login=(self.streamer.value or '').strip().lower()
        p=self.app.config['pipeline']['preview']
        if p['enabled']==value and p.get('test_streamer','')==login:return
        if self.app.save_config(lambda c:c['pipeline']['preview'].update(enabled=value,test_streamer=login)):self.app.dialogs.toast('Сохранено','ok')

    # ---------- test on a finished clip ----------
    async def _test(self):
        import asyncio,gpt_previews as gp
        app=self.app
        if self.running:await app.dialogs.info('Превью','Генерация уже идёт.');return
        files=await app.file_picker.pick_files(dialog_title='Выберите готовую нарезку',allowed_extensions=['mp4'],initial_directory=str(app.root/'recordings'))
        if not files or not files[0].path:return
        video=Path(files[0].path)
        job=video.parent.parent if video.parent.name in ('Готовые без тишины','Готовые нарезки') else video.parent
        m=re.match(r'([a-z0-9_]{1,25}) VOD \d+$',job.name)
        login=m.group(1) if m else (self.streamer.value or '').strip().lower()
        if not login:await app.dialogs.error('Превью','Для тестового видео укажите «Стример для тестовых видео».');return
        self.running=True;self.ring.visible=True;self.status.value=f'Генерирую превью ({login})…';self.status.color=None;self.result.controls=[];app.page.update()
        try:
            info=await asyncio.to_thread(gp.generate_for_clip,app.root,app.finder,video,login,app.config['pipeline']['preview'],lambda msg:app.post('preview_status',msg))
        except Exception as exc:
            self.status.value='Не получилось';self.status.color='#ff8a8a';await app.dialogs.error('Превью',str(exc))
        else:
            self.status.value='Превью сохранено';self.status.color='#6fdc9b'
            items=[]
            try:items.append(ft.Image(src=Path(info['path']).read_bytes(),width=640,height=360,fit=ft.BoxFit.CONTAIN,border_radius=12))
            except OSError:pass
            items+=[ft.Text('Надпись: '+info['preview_text'],size=14,weight=ft.FontWeight.W_600),muted('Контекст: '+info['context'],size=12),muted('Шаблон: '+info['template'],size=12),
                    ft.Row([ft.FilledButton('Открыть',icon=ft.Icons.OPEN_IN_NEW,on_click=lambda e,p=info['path']:app.open_path(p)),
                            ft.OutlinedButton('Папка',icon=ft.Icons.FOLDER_OPEN,on_click=lambda e,p=info['path']:app.open_path(str(Path(p).parent)))],spacing=10)]
            self.result.controls=items
        finally:
            self.running=False;self.ring.visible=False;app.refresh_soon()

    def _cancel(self):
        """Generation runs inside one ChatGPT request; it cannot be interrupted safely."""

    async def on_event(self,kind,value):
        if kind=='preview_status':self.status.value=str(value)[:200]


class BlurView:
    def __init__(self,app):
        self.app=app;self._key=None
        b=app.config['pipeline']['banner_blur']
        self.enabled=ft.Switch(label='Размывать области по профилю стримера',value=bool(b['enabled']),on_change=lambda e:app.spawn(self._save))
        self.streamer=ft.TextField(label='Ник стримера для тестового видео',value=b.get('test_streamer',''),width=320,
                                   on_blur=lambda e:app.spawn(self._save),on_submit=lambda e:app.spawn(self._save))
        self.profiles=ft.Column(spacing=8)
        self.status=ft.Text('',size=13);self.ring=ft.ProgressRing(width=18,height=18,stroke_width=2,visible=False)
        self.view=ft.Column([
            page_header('Блюр','Области, которые размываются на всей нарезке'),
            card(self.enabled,self.streamer,title='Настройки',icon=ft.Icons.TUNE),
            card(ft.Row([ft.FilledButton('По последней записи стримера',icon=ft.Icons.LIVE_TV,on_click=lambda e:app.spawn(self._from_twitch)),
                         ft.FilledTonalButton('По локальному видео',icon=ft.Icons.VIDEO_FILE,on_click=lambda e:app.spawn(self._from_local)),
                         ft.OutlinedButton('Без блюра для стримера',icon=ft.Icons.BLUR_OFF,on_click=lambda e:app.spawn(self._no_blur))],spacing=10,wrap=True),
                 ft.Row([self.ring,self.status],spacing=10),
                 self.profiles,title='Профили стримеров',icon=ft.Icons.BLUR_ON,
                 subtitle='Для каждого стримера настройте профиль или укажите «Без блюра». Сохранённый стример добавляется в мониторинг.'),
        ],spacing=16,scroll=ft.ScrollMode.AUTO,expand=True)

    def _all_logins(self):
        """Все стримеры из мониторинга и карточек каналов + уже сохранённые профили блюра."""
        c=self.app.config;names=[]
        for raw in list(c.get('streamers',[]))+list((c.get('streamer_modes') or {}).keys())+manual_blur.profile_logins(self.app.root):
            try:n=manual_blur.normalize_login(raw)
            except ValueError:continue
            if n!='__test__' and n not in names:names.append(n)
        return names

    def refresh(self,snap):
        rows=[]
        for name in self._all_logins():
            if not manual_blur.profile_path(self.app.root,name).exists():
                rows.append((name,'missing'));continue
            try:n=len(manual_blur.load_profile(self.app.root,name)['boxes'])
            except Exception:n=None
            rows.append((name,n))
        rows.sort(key=lambda r:(r[1]!='missing',r[0]))    # ненастроенные — сверху
        if rows==self._key:return
        self._key=rows
        def label(n):
            if n=='missing':return chip('не настроен','warn')
            if n==0:return chip('Без блюра','muted')
            if n is None:return chip('ошибка профиля','error')
            return chip(f'областей: {n}','info')
        self.profiles.controls=[ft.Container(ft.Row([ft.Icon(ft.Icons.PERSON,size=18,color=MUTED),ft.Text(name,size=14,weight=ft.FontWeight.W_600,expand=True),
                                                     label(n),
                                                     ft.IconButton(ft.Icons.EDIT,tooltip='Настроить по последней записи',on_click=lambda e,name=name:self.app.spawn(self._from_twitch,name)),
                                                     ft.IconButton(ft.Icons.BLUR_OFF,tooltip='Без блюра',on_click=lambda e,name=name:self.app.spawn(self._no_blur,name))],spacing=6),
                                             padding=ft.Padding.symmetric(horizontal=12,vertical=4),bgcolor='#1d2026',border_radius=10) for name,n in rows] or [empty('Стримеров пока нет')]

    async def _save(self):
        value=bool(self.enabled.value);login=(self.streamer.value or '').strip().lower()
        b=self.app.config['pipeline']['banner_blur']
        if b['enabled']==value and b.get('test_streamer','')==login:return
        if self.app.save_config(lambda c:c['pipeline']['banner_blur'].update(enabled=value,test_streamer=login)):self.app.dialogs.toast('Сохранено','ok')

    async def _login(self,name=None):
        if name:return name
        name=await self.app.dialogs.prompt('Блюр стримера','Twitch-ник стримера')
        if name is None:return None
        try:return manual_blur.normalize_login(name)
        except ValueError:await self.app.dialogs.error('Блюр','Введите корректный логин Twitch: латинские буквы, цифры или _.');return None

    def _saved(self,name):
        self._key=None
        added=self.app.add_streamer(name)
        self.status.value=f'Профиль {name} сохранён'+(' и добавлен в мониторинг.' if added else '.')

    async def _picker(self,name,image):
        from .blur_picker import BlurPicker
        try:await BlurPicker(self.app,name,image,lambda:self._saved(name)).run()
        except Exception as exc:await self.app.dialogs.error('Блюр',str(exc))

    async def _no_blur(self,name=None):
        name=await self._login(name)
        if not name:return
        if not await self.app.dialogs.confirm('Без блюра',f'Сохранить профиль {name} без блюра? Старые области этого профиля будут заменены.'):return
        try:manual_blur.save_profile(self.app.root,name,[]);self._saved(name)
        except Exception as exc:await self.app.dialogs.error('Блюр',str(exc))

    async def _from_twitch(self,name=None):
        import asyncio,stream_cutter
        app=self.app;name=await self._login(name)
        if not name:return
        proxy=app.config['proxy'];p=app.config['pipeline']
        cli=app.root/'desktop'/'tools'/'TwitchDownloaderCLI'/'TwitchDownloaderCLI.exe'
        try:ffmpeg,_=stream_cutter.require_tools()
        except Exception as exc:await app.dialogs.error('Блюр',str(exc));return
        self.ring.visible=True;self.status.value=f'Получаю кадр последней записи {name}…';app.page.update()
        try:
            image,vod,t=await asyncio.to_thread(manual_blur.latest_frame,name,proxy['url'] if proxy['enabled'] and proxy['twitch_api'] else '',str(cli),ffmpeg,threads=p['download_threads'])
        except Exception as exc:
            self.ring.visible=False;self.status.value='Не удалось получить кадр';await app.dialogs.error('Блюр',str(exc));return
        self.ring.visible=False;self.status.value=f'Кадр VOD {vod}: {t} с';app.page.update()
        await self._picker(name,image)

    async def _from_local(self):
        import asyncio,banner_blur,stream_cutter
        app=self.app;name=await self._login()
        if not name:return
        files=await app.file_picker.pick_files(dialog_title='Выберите локальное видео',allowed_extensions=['mp4','mkv','ts','flv','mov','webm','avi'])
        if not files or not files[0].path:return
        raw=await app.dialogs.prompt('Кадр','Время кадра, секунды',value='0')
        if raw is None:return
        try:seconds=max(0.0,float(raw.replace(',','.')))
        except ValueError:await app.dialogs.error('Кадр','Введите число секунд.');return
        try:
            ffmpeg,_=stream_cutter.require_tools()
            image=await asyncio.to_thread(banner_blur.full_frame_at,files[0].path,seconds,ffmpeg)
        except Exception as exc:await app.dialogs.error('Блюр',str(exc));return
        await self._picker(name,image)
